sp_widget.script:
(function() { data.templates = [];
  try { var gr = new GlideRecord("x_1433041_identi_0_template"); gr.addQuery("active", true); gr.orderByDesc("sys_updated_on"); gr.setLimit(50); gr.query();
    while (gr.next()) { data.templates.push({ sys_id: gr.getValue("sys_id"), name: gr.getValue("name"), description: gr.getValue("description"), version: gr.getValue("version") || "1.0", question_count: gr.getValue("question_count") || "0", status: gr.getDisplayValue("status"), updated: gr.getDisplayValue("sys_updated_on") }); }
  } catch (e) { gs.error("IBAR Template List widget error: " + e.message); }
})();
